export const LINES = [["From the start?", 5.703, 6.663], ["All right.", 6.983, 7.783], ["A year ago I had forty windows open and couldn't find anything.", 8.183, 11.263], ["Then I installed a small program called Spaceman.", 11.623, 14.483], ["It tiles your windows.", 14.84, 16.226], ["They sit side by side, nothing on top of anything else, and they stay just where you put them.", 16.544, 21.63], ["It also gives you numbered workspaces.", 22.053, 24.08], ["If something's in the wrong place, you don't close it — you just move it to another number.", 24.44, 28.623], ["My work went on one, and my messages on two.", 29.008, 31.92], ["I had a camera on my front door, and that's only another window, so I put it on three.", 32.318, 36.72], ["You can float a window too, if you want to keep an eye on it.", 37.109, 39.52], ["I found it pleasing.", 39.975, 40.97], ["So I bought one or two more, and I gave each of my neighbours a workspace of their own.", 44.495, 48.553], ["Alan is four.", 48.953, 50.033], ["Juliana is five.", 50.393, 51.735], ["Dax is six.", 52.095, 53.24], ["I like to know my neighbours.", 53.622, 55.022], ["Dax's hedge was a little over the limit, so I took a few photographs, for the record.", 57.882, 62.671], ["And Juliana and I disagreed about which day the bins go out.", 68.531, 71.731], ["I'd kept seven empty, because it's useful to have somewhere to put things.", 76.131, 79.78], ["I moved Juliana there in March, and I've looked after her cat ever since.", 80.192, 83.753], ["I moved Alan in June.", 86.118, 87.393], ["Where is Dax now?", 88.493, 89.575], ["He's on seven, with the other two.", 90.66, 93.02], ["And what is on seven?", 94.735, 96.253], ["Only the one window.", 97.078, 98.255], ["They're side by side, nothing on top of anything else, and they stay just where I put them.", 98.575, 103.331], ["You should try it, Detective.", 105.526, 106.836], ["You look like a woman with a great many windows open.", 107.264, 109.504]]
